import sys

def mex(arr):
    # Helper function to find the minimum non-negative integer not present in the array
    for i in range(len(arr)):
        if arr[i] != i:
            return i
    return len(arr)

def max_mex_sum(n, m):
    # Create a matrix filled with -1
    matrix = [[-1 for _ in range(m)] for _ in range(n)]

    # Fill the matrix with unique values
    value = 0
    for i in range(n):
        for j in range(m):
            matrix[i][j] = value
            value += 1

    # Calculate the sum of mex for rows and columns
    row_sum = sum(mex(row) for row in matrix)
    col_sum = sum(mex(col) for col in zip(*matrix))

    # Return the total sum of mex
    return row_sum + col_sum

