def find_inside_string(a):
    # Initialize variables to keep track of the count of 'p', 'q', and 'w'
    p_count = q_count = w_count = 0

    # Count the occurrences of each character in the input string
    for char in a:
        if char == 'p':
            p_count += 1
        elif char == 'q':
            q_count += 1
        else:
            w_count += 1

    # Determine the length of the inside string based on the counts of 'p' and 'q'
    if p_count > q_count:
        return 'w' * (p_count - q_count)
    elif q_count > p_count:
        return 'p' * (q_count - p_count)
    else:
        return 'w' * (p_count + q_count)

