    count_p = 0
    count_q = 0
    count_w = 0

    for char in a:
        if char == 'p':
            count_p += 1
        elif char == 'q':
            count_q += 1
        else:
            count_w += 1

    # Determine the length of b based on the counts of p, q, and w
    if count_p > count_q or count_p > count_w:
        b_length = count_p + min(count_q, count_w)
    elif count_q > count_p or count_q > count_w:
        b_length = count_q + min(count_p, count_w)
    else:
        b_length = count_w + min(count_p, count_q)

    # Construct b based on the determined length
    for i in range(b_length):
        if i < count_p:
            result += 'p'
        elif i < count_p + count_q:
            result += 'q'
        else:
            result += 'w'

    return result

