def min_seconds(s, t):
    if s == t:
        return len(s)

    # Initialize variables
    m = len(s)
    n = len(t)
    dp = [[float('inf')] * (n + 1) for _ in range(m + 1)]
    prev = [[None] * (n + 1) for _ in range(m + 1)]

    # Fill the DP table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if s[i - 1] == t[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
                prev[i][j] = 'same'
            else:
                dp[i][j] = min(dp[i - 1][j], dp[i][j - 1]) + 1

    # Reconstruct the solution
    result = []
    i, j = m, n
    while i > 0 or j > 0:
        if prev[i][j] == 'same':
            result.append(s[i - 1])
            i -= 1
            j -= 1
        elif prev[i][j] == 'copy':
            result.append(s[i - 1])
            i -= 1
        else:
            result.append(t[j - 1])
            j -= 1

    # Reverse the result to get the correct order
    result.reverse()

    return len(result)

