def min_seconds(s, t):
    # Convert strings to sets for efficient lookup
    set_s = set(s)
    set_t = set(t)

    # Initialize variables to keep track of time and last copied position
    time = 0
    last_copied = -1

    # Iterate through the sequences
    for i in range(len(s)):
        if s[i] in set_t:
            # If the current character in s is in t, copy the sequence to the other screen
            if last_copied == -1 or last_copied < i:
                last_copied = i
                time += len(t)
            else:
                time += len(s) - i
        else:
            # If the current character in s is not in t, copy the sequence to the other screen
            if last_copied == -1 or last_copied < i:
                last_copied = i
                time += len(t)
            else:
                time += len(s) - i

    return time

