def check_divisibility(n):
    while n >= 10:
        last_digit = n % 10
        if last_digit == 0:
            return False
        elif last_digit == 1:
            n //= 10
            continue
        elif last_digit == 4 or last_digit == 7:
            n //= 10
            continue
        elif last_digit == 2:
            n //= 4
            continue
        elif last_digit == 5:
            n //= 5
            continue
        elif last_digit == 8:
            n //= 8
            continue
        else:
            return False
    return True

