def can_continue_indefinitely(n, times):
    # Check if all times are initially non-zero
    for time in times:
        if time == 0:
            return False

    # Check if the minimum time is greater than or equal to the maximum time
    min_time = min(times)
    max_time = max(times)
    if min_time > max_time:
        return True

    # Check if there exists a cycle
    visited = [False] * n
    stack = []

    def dfs(i):
        if visited[i]:
            return True
        visited[i] = True
        stack.append(i)

        for j in range(1, n):
            if times[j] < times[i] and not visited[(j + i) % n]:
                if dfs((j + i) % n):
                    return True

        stack.pop()
        return False

    for i in range(n):
        if not visited[i]:
            if dfs(i):
                return True

    return False

