def can_continue_indefinitely(n, a):
    # Check if all clocks have non-negative initial times
    for time in a:
        if time < 0:
            return False

    # Check if there exists a cycle in the graph formed by the clocks
    graph = [[] for _ in range(n)]
    for i in range(n):
        for j in range(i+1, n):
            if a[j] - a[i] > 0:
                graph[i].append(j)
                graph[j].append(i)

    visited = [False] * n
    def dfs(node):
        if visited[node]:
            return True
        visited[node] = True
        for neighbor in graph[node]:
            if dfs(neighbor):
                return True
        return False

    for i in range(n):
        if not visited[i] and dfs(i):
            return True

    return False

