def min_length(s):
    if len(s) <= 1:
        return len(s)

    # Find consecutive repeating characters
    repeat_indices = []
    for i in range(1, len(s)):
        if s[i] == s[i-1]:
            repeat_indices.append(i)

    # Remove consecutive repeating characters
    while repeat_indices:
        start_index = repeat_indices.pop(0)
        end_index = start_index + 1
        while end_index < len(s) and s[end_index] == s[start_index]:
            end_index += 1

        s = s[:start_index] + s[end_index:]

    return len(s)

