def min_magic_steps(matrix: List[List[int]]) -> int:
    n = len(matrix)
    directions = [(1, 1), (-1, 1), (1, -1), (-1, -1)]

    def dfs(i, j):
        if i == n or j == n or matrix[i][j] >= 0:
            return True
        for dx, dy in directions:
            nx, ny = i + dx, j + dy
            if 0 <= nx < n and 0 <= ny < n and dfs(nx, ny):
                matrix[i][j] += 1
                return True
        return False

    steps = 0
    for _ in range(n):
        changed = False
        for i in range(n):
            for j in range(n):
                if matrix[i][j] < 0 and dfs(i, j):
                    changed = True
                    break
            if changed:
                break
        if not changed:
