def can_sort_by_swaps(p):
    n = len(p)
    # Check if the permutation is already sorted
    if sorted(p) == p:
        return "YES"

    # Count the number of inversions
    inversion_count = 0
    for i in range(n):
        for j in range(i + 1, n):
            if p[i] > p[j]:
                inversion_count += 1

    # If there are more than half the permutations that need to be swapped, it's not possible
    if inversion_count > n // 2:
        return "NO"

    return "YES"

