def calculate_factorial(n):
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result

def find_odd_divisors(n, d):
    factorial = calculate_factorial(n)
    divisor = int(factorial / d)
    odd_divisors = []

    while divisor > 0:
        if divisor % 2 != 0:
            odd_divisors.append(divisor)
        divisor //= 2

    odd_divisors.sort()
    return odd_divisors

