def min_subseq_sum(a, l, r):
    # Find the minimum prefix sum of the subarray [l, r]
    min_prefix = float('inf')
    current_prefix = 0
    for i in range(l, r + 1):
        current_prefix += a[i]
        if current_prefix < min_prefix:
            min_prefix = current_prefix

    # Find the maximum suffix sum of the subarray [l, r]
    max_suffix = float('-inf')
    current_suffix = 0
    for i in range(r, l - 1, -1):
        current_suffix += a[i]
        if current_suffix > max_suffix:
            max_suffix = current_suffix

    # Calculate the minimum sum of the subarray [l, r]
    return min(min_prefix + max_suffix - a[l], a[l] + max_suffix - a[r])

