from typing import List

def max_score(arr: List[int]) -> int:
    # Initialize the arrays b and c
    b = []
    c = []

    # Calculate b and c
    for num in arr:
        if len(b) == 0 or num < b[-1]:
            b.append(num)
        else:
            b.append(b[-1])

        if len(c) == 0 or num > c[-1]:
            c.append(num)
        else:
            c.append(c[-1])

    # Calculate the score
    score = sum(c[i] - b[i] for i in range(len(arr)))
    return score

