def calculate_manhattan_distances(n, m, r, c):
    total_distance = 0
    for i in range(1, n * m + 1):
        if i == r * m + c:
            continue
        previous_position = (i - 1) // m, (i - 1) % m
        distance = abs(r - previous_position[0]) + abs(c - previous_position[1])
        total_distance += distance
    return total_distance

