        count = arr.count(min_val)
        if count <= k:
            return 1
        else:
            return f(arr[:arr.index(min_val)] + arr[arr.index(min_val)+count:])

    max_value = max(arr)
    if max_value > k:
        return -1

    result = float('inf')
    for i in range(1, max_value + 1):
        result = min(result, f([i]*max_value))

    return result

