from collections import Counter

def find_dimensions(shuffled_inputs):
    count = Counter(shuffled_inputs)
    n = len(count)
    m = int(n ** 0.5)

    if m * m == n:
        return m, m

    for i in range(1, n + 1):
        if i * i > n:
            break
        if n % i == 0:
            j = n // i
            if i * j == n and count[i] >= i and count[j] >= j:
                return i, j

    return -1, -1

