import sys

def find_grid_dimensions(shuffled_inputs):
    # Create a frequency dictionary to count occurrences of each number
    num_counts = {}
    for num in shuffled_inputs:
        if num in num_counts:
            num_counts[num] += 1
        else:
            num_counts[num] = 1

    # Find the maximum frequency which will be the sum of n + m - 1
    max_freq = max(num_counts.values())

    # Since n + m - 1 must be greater than or equal to the length of the shuffled list,
    # we can start with n + m - 1 and check if we can split the list into two parts
    # such that the sums of the two parts are equal.
    for n_plus_m_minus_1 in range(max_freq, len(shuffled_inputs) + 1):
        n = n_plus_m_minus_1 // 2
        m = n_plus_m_minus_1 - n

        # Check if we can split the list into two parts with equal sums
        if sum(shuffled_inputs[:n]) == sum(shuffled_inputs[n:]):
            return n, m

    # If no valid solution is found, return None
    return None

