def min_sort_possible(n, sequence):
    if n == 1:
        return "YES"

    # Find the minimum value in the array
    min_value = min(sequence)

    # If the minimum value is greater than or equal to the second element,
    # it's always possible to make the array non-decreasing
    if min_value >= sequence[1]:
        return "YES"

    # Check if we can make the array non-decreasing by removing the minimum value
    for i in range(n):
        if sequence[i] == min_value:
            # Remove the minimum value and check if the remaining array is non-decreasing
            if check_non_decreasing(sequence[:i] + sequence[i+1:]):
                return "YES"
    return "NO"

