            a[i + 1] -= min_val
    return all(x <= y for x, y in zip(a, a[1:]))

def main():
    t = int(input())
    for _ in range(t):
        n = int(input())
        a = list(map(int, input().split()))
        if can_make_non_decreasing(n, a):
            print("YES")
        else:
            print("NO")

if __name__ == "__main__":
    main()
